package main

import (
	"context"
	"flag"
	"os"
	"os/signal"

	"legagent/app/services"
)

// runInitProceedings 建立議會會議、文稿、議案與表決的 PostgreSQL 資料表。
//
//	go run . init-proceedings
//
// @ai:generated by=claude-opus-5-5 date=2026-11-05
// @ai:purpose 建表是明確的維運動作，與伺服器啟動分開
// @ai:input args 子命令參數
// @ai:output none
// @ai:sideeffect 建立 proceedings schema 與資料表、失敗時 os.Exit
func runInitProceedings(args []string) {
	fs := flag.NewFlagSet("init-proceedings", flag.ExitOnError)
	cfgPath := fs.String("config", defaultConfigPath, "config.yaml 路徑")
	_ = fs.Parse(args)

	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt)
	defer stop()

	cfg, log := mustLoad(*cfgPath)
	db := mustOpenDB(cfg, log)
	defer db.Close()

	if err := services.EnsureProceedingsSchema(ctx, db, log); err != nil {
		db.Close()
		os.Exit(1)
	}
	log.Info("proceedings schema ready", "tables", len(services.ProceedingsTables))
}
